Check(new[] { "Học C#", "Học SQL", "Ôn C#" }, "C#", new[] { "Học C#", "Ôn C#" });
Check(new[] { "học c#" }, "C#", Array.Empty<string>());
Check(Array.Empty<string>(), "C#", Array.Empty<string>());
Console.WriteLine("3 ca kiểm tra đạt");
static void Check(string[] source, string keyword, string[] expected)
{
    string[] actual = source.Where(line => line.Contains(keyword, StringComparison.Ordinal)).ToArray();
    if (!actual.SequenceEqual(expected)) throw new Exception("Kết quả lọc không đúng yêu cầu");
}

